import Foundation
import FoundationModels

/// Five-words-max labels for list rows (Tony's rule, Nov 6: a summary
/// is a label, not a sentence). Generated by Apple's on-device language
/// model when it is available; when it isn't, the opening words of the
/// text stand in, capped the same way. Runs when a recording is
/// finished, when a book is imported, lazily for anything that lacks a
/// label — and again for older rows whose one-sentence summaries
/// predate the five-word rule.
@MainActor
enum Summarizer {
    private static var inFlight: Set<UUID> = []

    static func generateIfNeeded(for document: Document) {
        if let summary = document.summary, !summary.isEmpty, wordCount(summary) <= 5 { return }
        guard !inFlight.contains(document.id) else { return }
        let source = sourceText(for: document)
        guard source.count > 40 else { return }
        inFlight.insert(document.id)
        Task {
            let summary = await summarize(source)
            inFlight.remove(document.id)
            if let summary, !summary.isEmpty {
                document.summary = summary
                try? document.modelContext?.save()
            }
        }
    }

    /// What gets summarized: a recording's transcript, or a book's opening.
    static func sourceText(for document: Document) -> String {
        switch document.kind {
        case .recording:
            return document.transcript.plain
        case .book:
            var text = ""
            for chapter in document.chapters {
                if !text.isEmpty { text += "\n" }
                text += chapter.text
                if text.count >= 6000 { break }
            }
            return text
        }
    }

    static func summarize(_ source: String) async -> String? {
        let trimmed = source.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }
        if SystemLanguageModel.default.isAvailable {
            do {
                let session = LanguageModelSession(
                    instructions: "You write a label of AT MOST FIVE WORDS that captures what a text is about, so the label can stand in for the text in a list. Reply with the label only: no preamble, no quotes, no markdown, no ending punctuation."
                )
                let response = try await session.respond(to: "Label this text in at most five words:\n\n\(String(trimmed.prefix(6000)))")
                let label = cappedAtFiveWords(response.content)
                if !label.isEmpty {
                    return label
                }
            } catch {
                // Model unavailable mid-flight, guardrails, or context
                // limits — fall through to the plain rule below.
            }
        }
        return fallbackLabel(for: trimmed)
    }

    /// The fallback: the first sentence's opening, capped at five words
    /// like everything else.
    static func fallbackLabel(for text: String) -> String? {
        var first: String?
        text.enumerateSubstrings(in: text.startIndex..<text.endIndex, options: [.bySentences, .localized]) { substring, _, _, stop in
            if let substring, !substring.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                first = substring
                stop = true
            }
        }
        let raw = (first ?? text).trimmingCharacters(in: .whitespacesAndNewlines)
        let label = cappedAtFiveWords(raw)
        return label.isEmpty ? nil : label
    }

    static func wordCount(_ text: String) -> Int {
        text.split(whereSeparator: { $0.isWhitespace }).count
    }

    /// Hard cap, applied to model output and fallback alike: the first
    /// five whitespace-separated words, whatever came back.
    static func cappedAtFiveWords(_ text: String) -> String {
        let words = text.trimmingCharacters(in: .whitespacesAndNewlines)
            .split(whereSeparator: { $0.isWhitespace })
        return words.prefix(5).joined(separator: " ")
    }
}
